<template>
  <div class="course-list-page">
    <header class="page-header"><div><h2>我的课程</h2><p>加入课堂，查看学习资料、班级成员与个人学习总结</p></div></header>
    <section class="search-bar"><el-input v-model="searchId" placeholder="输入课程号搜索" clearable @keyup.enter="search"><template #prefix><i class="ph ph-magnifying-glass" aria-hidden="true" /></template></el-input><el-button type="primary" :loading="searching" @click="search">搜索</el-button></section>
    <section v-if="searchResult" class="search-result"><div><h3>{{ searchResult.courseName }}</h3><p>课程号 {{ searchResult.courseId }} · {{ searchResult.isFinished === 1 ? '已结课' : '进行中' }}<span v-if="searchResult.maxStudents"> · 上限 {{ searchResult.maxStudents }} 人</span></p></div><el-button type="primary" :loading="joining" :disabled="searchResult.isFinished === 1 || isJoined(searchResult.courseId) || isPending(searchResult.courseId)" @click="join(searchResult.courseId)">{{ isJoined(searchResult.courseId) ? '已加入' : isPending(searchResult.courseId) ? '等待教师审核' : searchResult.approvalRequired ? '申请加入' : '加入班级' }}</el-button></section>
    <section v-if="visibleApplications.length" class="application-status"><div class="application-head"><h3>我的入课申请</h3><button type="button" class="close-applications" aria-label="关闭入课申请" @click="dismiss"><i class="ph ph-x" aria-hidden="true" /></button></div><div v-for="a in visibleApplications" :key="a.courseId" class="application-row"><span>{{ a.courseName }}</span><el-tag :type="a.status === 'PENDING' ? 'warning' : a.status === 'APPROVED' ? 'success' : 'info'">{{ {PENDING:'等待审核',APPROVED:'已通过',REJECTED:'未通过，可重新申请'}[a.status] }}</el-tag></div></section>
    <div class="list-title"><h3>已选课程</h3><el-button text :loading="loading" @click="load">刷新</el-button></div>
    <el-skeleton v-if="loading && !courses.length" :rows="5" animated /><el-empty v-else-if="!courses.length" description="暂未加入课程，可通过课程号搜索加入" />
    <div v-else class="course-grid"><article v-for="course in courses" :key="course.courseId" class="course-card"><div class="course-cover"><img v-if="course.coverUrl" :src="course.coverUrl" alt="课程封面" /><template v-else><i class="ph ph-books" aria-hidden="true" /><span>LEARNING</span></template><el-tag class="status" :type="course.isFinished === 1 ? 'info' : 'success'">{{ course.isFinished === 1 ? '已结课' : '进行中' }}</el-tag></div><div class="course-body"><h3>{{ course.courseName }}</h3><p class="course-id">课程号 {{ course.courseId }} · {{ scoreMap[course.courseId]?.teacherName || '主讲教师 '+course.teacherId }}</p><div class="course-meta"><span><i class="ph ph-users" aria-hidden="true" /> {{ course.memberCount || 0 }} 位成员</span><span><i class="ph ph-clock" aria-hidden="true" /> {{ course.fixedSchedule ? `每周${weekdays[course.classWeekday-1]} ${course.classTime}` : '授课时间灵活安排' }}</span></div><div class="score-row"><span>本课得分</span><strong>{{ formatScore(scoreMap[course.courseId]?.studentScore) }}</strong></div><div class="student-actions"><el-button type="primary" plain @click="router.push(`/student/courses/${course.courseId}`)">课程详情 <i class="ph ph-arrow-right" aria-hidden="true" /></el-button><el-button v-if="live(course.courseId)?.mode === 'ONLINE'" type="success" plain @click="router.push(`/student/live/${live(course.courseId).sessionId}`)">进入直播间</el-button><el-button type="danger" text :disabled="course.isFinished === 1" @click="leave(course)">退课</el-button></div></div></article></div>
  </div>
</template>
<script setup>
import {computed,onMounted,onUnmounted,reactive,ref} from 'vue'
import {useRouter} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import {fetchStudentCourses,fetchMyCourseScores,searchCourse,joinCourse,leaveCourse} from '@/api/course'
import {fetchApplications} from '@/api/classroom'
import {dismissCourseApplications} from '@/api/courseWorkspace'
import {useClassroomStore} from '@/stores/classroom'
const router=useRouter(),classroom=useClassroomStore(),courses=ref([]),applications=ref([]),scoreMap=reactive({}),loading=ref(false),searching=ref(false),joining=ref(false),searchId=ref(''),searchResult=ref(null)
const weekdays=['一','二','三','四','五','六','日'],visibleApplications=computed(()=>applications.value.filter(a=>!Number(a.studentHidden)))
const isJoined=id=>courses.value.some(c=>String(c.courseId)===String(id)),isPending=id=>applications.value.some(a=>String(a.courseId)===String(id)&&a.status==='PENDING'),live=id=>classroom.liveClasses.find(c=>String(c.courseId)===String(id))
const formatScore=value=>value==null?'-':Number(value).toFixed(1)
let timer
async function load(){loading.value=true;try{const [c,s,a]=await Promise.all([fetchStudentCourses(),fetchMyCourseScores(),fetchApplications('student')]);courses.value=c.data||[];applications.value=a.data||[];Object.keys(scoreMap).forEach(k=>delete scoreMap[k]);for(const item of s.data||[])scoreMap[item.courseId]=item}catch{}finally{loading.value=false}}
async function search(){if(!searchId.value.trim()){ElMessage.warning('请输入课程号');return}searching.value=true;try{searchResult.value=(await searchCourse(searchId.value.trim())).data}catch{searchResult.value=null}finally{searching.value=false}}
async function join(id){joining.value=true;try{const r=await joinCourse(id);ElMessage.success(r.message);await load()}catch{}finally{joining.value=false}}
async function leave(c){try{await ElMessageBox.confirm(`确认退出「${c.courseName}」？`,'退出课程');await leaveCourse(c.courseId);await load();ElMessage.success('已退出课程')}catch{}}
async function dismiss(){try{await dismissCourseApplications();applications.value.forEach(a=>{a.studentHidden=1})}catch{}}
onMounted(()=>{load();timer=setInterval(load,10000)});onUnmounted(()=>clearInterval(timer))
</script>
